function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || '' || payload.query || '').trim();
  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const normalized = normalize(raw);
const prefixes = ['them vao doc', 'append doc', 'ghi them vao tai lieu'];
let body = raw;
for (const prefix of prefixes) {
  if (normalized.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

let docId = source.docId || source.documentId || source.fileId || source.targetId || args.docId || args.documentId || args.fileId || args.targetId || ctx.payload.docId || ctx.payload.documentId || ctx.payload.fileId || ctx.payload.targetId || '';
let docName = cleanName(source.docName || source.targetName || source.fileName || args.docName || args.targetName || args.fileName || ctx.payload.docName || ctx.payload.targetName || ctx.payload.fileName || '');
let content = String(source.content || args.content || '').trim();

if ((!docName || !content) && body) {
  const separator = body.indexOf(':');
  if (separator !== -1) {
    docName = docName || cleanName(body.slice(0, separator));
    content = content || body.slice(separator + 1).trim();
  } else {
    const markerMatch = body.match(/\s+(?:noi dung|nội dung|content)\s*[:=-]?\s*/i);
    if (markerMatch) {
      const idx = markerMatch.index || 0;
      docName = docName || cleanName(body.slice(0, idx));
      content = content || body.slice(idx + markerMatch[0].length).trim();
    }
  }
}



// Stage 11 exact-id safety guard
const __stage11Pick = (...values) => {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return value;
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
    if (typeof value === 'boolean') return value;
  }
  return '';
};
const __stage11Source = source || {};
const __stage11Args = args || __stage11Source.args || __stage11Source.payload?.args || {};
const __stage11Payload = typeof payload !== 'undefined' ? payload : (__stage11Source.payload || {});
const __stage11IdFields = ["docId", "documentId", "fileId", "targetId"];
const __stage11AlsoFields = [];
const __stage11HasId = Boolean(__stage11Pick(...__stage11IdFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11HasAlso = __stage11AlsoFields.length === 0 || Boolean(__stage11Pick(...__stage11AlsoFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11Allowed = __stage11HasId && __stage11HasAlso;
const __stage11Response = __stage11Allowed ? '' : "Mia chưa ghi thêm vào Google Doc vì hành động này cần docId/documentId cụ thể. Bạn hãy tìm hoặc đọc tài liệu trước để lấy đúng ID rồi gửi lại nội dung cần thêm nhé.";

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text: normalized,
    docId,
    targetId: docId,
    docName,
    targetName: docName,
    content,
    hasTarget: Boolean(__stage11Allowed && (docId || docName)),
    hasContent: Boolean(content),
    response: __stage11Response ? __stage11Response : (docId || docName) && content ? '' : '📝 <b>Append Google Doc</b>\n\nVi du: <code>them vao doc Project Plan: dong moi</code>'
  }
}];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, docId: '', response: 'Mia chưa tìm thấy Google Doc phù hợp.' } }];
}
const doc = rows[0];
return [{ json: { ...source, docId: doc.id || source.docId || source.targetId || '', documentId: doc.id || source.documentId || source.docId || source.targetId || '', fileId: doc.id || source.fileId || source.docId || source.targetId || '', targetId: source.targetId || doc.id || source.docId || source.documentId || '', docName: doc.name || source.docName || source.targetName || '', targetName: source.targetName || doc.name || source.docName || '', fileName: source.fileName || source.docName || source.targetName || doc.name || '', webViewLink: doc.webViewLink || '' } }];

const source = $('Prepare Action').item.json || {};

const resolved = (() => {
  try {
    return $('Resolve Search Result').item.json || {};
  } catch (e) {
    return {};
  }
})();

const doc = (() => {
  try {
    return $('Docs Get Document').item.json || {};
  } catch (e) {
    return {};
  }
})();

const documentId =
  source.documentId ||
  source.docId ||
  source.fileId ||
  source.targetId ||
  resolved.documentId ||
  resolved.docId ||
  resolved.fileId ||
  resolved.targetId ||
  resolved.id ||
  doc.documentId ||
  '';

const title =
  resolved.name ||
  resolved.title ||
  doc.title ||
  source.title ||
  source.docName ||
  source.targetName ||
  source.query ||
  'Không rõ tên';

const content = String(
  source.content ||
  source.appendContent ||
  source.textToAppend ||
  ''
).trim();

if (!documentId) {
  throw new Error('Missing documentId. Cannot append Google Docs content.');
}

if (!content) {
  throw new Error('Missing content. Cannot append empty content to Google Docs.');
}

const bodyContent = Array.isArray(doc.body?.content)
  ? doc.body.content
  : [];

let insertIndex = 1;

if (bodyContent.length) {
  const last = bodyContent[bodyContent.length - 1];
  const endIndex = Number(last.endIndex || 2);

  // Google Docs cần insert trước ký tự newline cuối document.
  insertIndex = Math.max(1, endIndex - 1);
}

const appendText = '\n' + content;

return [{
  json: {
    ...source,
    ...resolved,

    chatId: source.chatId || resolved.chatId || '',
    documentId,
    docId: documentId,
    fileId: documentId,
    targetId: source.targetId || resolved.targetId || documentId,
    docName: source.docName || resolved.docName || source.targetName || resolved.targetName || title,
    targetName: source.targetName || resolved.targetName || source.docName || resolved.docName || title,
    title,
    content,
    insertIndex,
    appendLength: appendText.length,

    body: {
      requests: [
        {
          insertText: {
            location: {
              index: insertIndex
            },
            text: appendText
          }
        }
      ]
    }
  }
}];

const source = $('Build Append Request').item.json || $('Prepare Action').item.json || {};
const docId = source.docId || '';
const link = source.webViewLink || (docId ? `https://docs.google.com/document/d/${docId}/edit` : '');
const charCount = String(source.content || '').length;
const docName = source.docName || source.targetName || 'Không rõ tên';

let text = `Đã thêm nội dung vào Google Doc: ${docName}`;
if (docId) text += `\nID: ${docId}`;
text += `\nSố ký tự đã thêm: ${charCount}`;
if (link) text += `\nMở tài liệu: ${link}`;

return [{ json: { chatId: source.chatId || '', text: text.trim() } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
